// Parse AI response, calculate scores, and build final report
try {
  const data = $('Process & Analyze').item.json;
  const aiResponse = $input.item.json;

  // Parse AI response with robust error handling
  let aiData;
  try {
    const content = aiResponse.message?.content || aiResponse.text || JSON.stringify(aiResponse);

    // Remove markdown code blocks if present
    const cleanContent = content.replace(/```(?:json)?\s*([\s\S]*?)```/g, '$1').trim();

    aiData = JSON.parse(cleanContent);
  } catch (parseError) {
    // Fallback AI data if parsing fails
    aiData = {
      intent: {
        primary: 'Mixed',
        confidence: {
          informational: 50,
          commercial: 30,
          transactional: 15,
          navigational: 5
        },
        reasoning: 'AI parsing failed, using default classification'
      },
      clusters: [
        {
          topic: 'Primary Topic',
          keywords: [data.keyword, ...data.relatedKeywords.slice(0, 3).map(k => k.keyword)],
          primary: data.keyword,
          secondary: data.relatedKeywords.slice(0, 3).map(k => k.keyword),
          page_type: 'guide',
          angle: 'Comprehensive guide approach'
        }
      ]
    };
  }

  const serpOverview = data.serpOverview || [];
  const authorityMetrics = data.authorityMetrics || {};
  const contentGaps = data.contentGaps || {};
  const intentData = aiData.intent || {};
  const clusters = aiData.clusters || [];

  // === DIFFICULTY SCORE (0-100, higher = harder) ===
  let difficultyScore = 0;

  // 1. Domain Authority (0-35 points)
  const highAuthorityRatio = authorityMetrics.highAuthorityCount / Math.max(authorityMetrics.totalResults, 1);
  difficultyScore += highAuthorityRatio * 35;

  // 2. Domain Concentration (0-25 points)
  const concentration = authorityMetrics.domainConcentration || 0;
  if (concentration > 0.3) {
    difficultyScore += 25; // High concentration = harder
  } else if (concentration > 0.15) {
    difficultyScore += 15;
  } else {
    difficultyScore += 5;
  }

  // 3. Content Saturation (0-20 points)
  const saturatedThemes = (contentGaps.repeatedCompetitorAngles || []).length;
  difficultyScore += Math.min(saturatedThemes * 5, 20);

  // 4. Intent Competition (0-20 points)
  const intentScores = intentData.confidence || {};
  if (intentScores.transactional > 60) {
    difficultyScore += 20;
  } else if (intentScores.commercial > 60) {
    difficultyScore += 15;
  } else if (intentScores.informational > 60) {
    difficultyScore += 8;
  } else {
    difficultyScore += 12;
  }

  difficultyScore = Math.min(Math.round(difficultyScore), 100);

  // === OPPORTUNITY SCORE (0-100, higher = better) ===
  let opportunityScore = 0;

  // 1. Content Gaps (0-35 points)
  const missingCount = (contentGaps.missingSubtopics || []).length;
  const thinCount = (contentGaps.thinContentAreas || []).length;
  opportunityScore += Math.min(missingCount * 8 + thinCount * 4, 35);

  // 2. Keyword Variety (0-25 points)
  const keywordCount = (data.relatedKeywords || []).length;
  opportunityScore += Math.min(keywordCount * 1.5, 25);

  // 3. Intent Alignment (0-25 points)
  if (intentData.primary === 'Informational' || intentData.primary === 'Commercial') {
    opportunityScore += 25;
  } else if (intentData.primary === 'Mixed') {
    opportunityScore += 18;
  } else {
    opportunityScore += 10;
  }

  // 4. Low Competition Bonus (0-15 points)
  if (difficultyScore < 35) {
    opportunityScore += 15;
  } else if (difficultyScore < 55) {
    opportunityScore += 10;
  } else if (difficultyScore < 70) {
    opportunityScore += 5;
  }

  opportunityScore = Math.min(Math.round(opportunityScore), 100);

  // === PRIORITY CLASSIFICATION ===
  let priority = 'Low';
  const combinedScore = opportunityScore - (difficultyScore * 0.65);

  if (combinedScore > 35 && opportunityScore > 65) {
    priority = 'High';
  } else if (combinedScore > 15 && opportunityScore > 45) {
    priority = 'Medium';
  }

  // === BUILD FINAL REPORT ===
  const scoReport = {
    keyword: data.keyword,
    search_intent: {
      primary: intentData.primary || 'Mixed',
      confidence_scores: intentData.confidence || {},
      reasoning: intentData.reasoning || ''
    },
    difficulty_score: difficultyScore,
    opportunity_score: opportunityScore,
    priority: priority,
    score_breakdown: {
      difficulty_factors: {
        domain_authority: Math.round(highAuthorityRatio * 35),
        domain_concentration: concentration > 0.3 ? 25 : (concentration > 0.15 ? 15 : 5),
        content_saturation: Math.min(saturatedThemes * 5, 20),
        intent_competition: intentScores.transactional > 60 ? 20 : (intentScores.commercial > 60 ? 15 : (intentScores.informational > 60 ? 8 : 12))
      },
      opportunity_factors: {
        content_gaps: Math.min(missingCount * 8 + thinCount * 4, 35),
        keyword_variety: Math.min(keywordCount * 1.5, 25),
        intent_alignment: intentData.primary === 'Informational' || intentData.primary === 'Commercial' ? 25 : (intentData.primary === 'Mixed' ? 18 : 10),
        low_competition_bonus: difficultyScore < 35 ? 15 : (difficultyScore < 55 ? 10 : (difficultyScore < 70 ? 5 : 0))
      },
      combined_score: parseFloat(combinedScore.toFixed(2))
    },
    serp_overview: serpOverview,
    content_gaps: {
      missing_subtopics: contentGaps.missingSubtopics || [],
      thin_content_areas: contentGaps.thinContentAreas || [],
      repeated_competitor_angles: contentGaps.repeatedCompetitorAngles || [],
      content_opportunities: contentGaps.contentOpportunities || [],
      content_themes: contentGaps.contentThemes || {}
    },
    keyword_clusters: clusters,
    related_keywords: data.relatedKeywords || [],
    serp_features: data.serpFeatures || {},
    metadata: {
      search_depth: data.depth,
      total_serp_results: serpOverview.length,
      total_related_keywords: data.relatedKeywords.length,
      total_clusters: clusters.length,
      authority_metrics: authorityMetrics,
      timestamp: data.timestamp,
      workflow_version: '2.0-optimized'
    }
  };

  return scoReport;

} catch (error) {
  throw new Error(`Report building failed: ${error.message}`);
}
